/**
 * Material Trader view model: the same exchange arithmetic as
 * omnicovas/features/material_trader.py, for immediate quotes and basket
 * simulation in the browser. Integers only; a contract test compares these
 * results with quotes generated by the backend engine.
 *
 * Cost of one received unit, in units given: x6 per grade up, x1/3 per grade
 * down, x6 once across groups. A trade is whole lots of the reduced ratio.
 */

const gcd = (a, b) => (b ? gcd(b, a % b) : a);

export function buildTraderIndex(trader) {
  const materials = new Map();
  (trader?.materials || []).forEach((row) => materials.set(row.id, row));
  return {
    available: trader?.state === 'available',
    known: trader?.inventory_state === 'verified_local',
    exchange: trader?.exchange || { up_one_grade_cost: 6, down_one_grade_yield: 3, group_change_cost: 6 },
    materials,
    groups: trader?.groups || [],
  };
}

/** `[pay, receive]` for the smallest whole exchange, or null when no trade exists. */
export function lot(index, give, take) {
  const source = index.materials.get(give);
  const target = index.materials.get(take);
  if (!source || !target || give === take || source.type !== target.type) return null;
  const steps = target.grade - source.grade;
  let num = steps >= 0 ? index.exchange.up_one_grade_cost ** steps : 1;
  let den = steps < 0 ? index.exchange.down_one_grade_yield ** -steps : 1;
  if (source.group !== target.group) num *= index.exchange.group_change_cost;
  const divisor = gcd(num, den);
  return [num / divisor, den / divisor];
}

export function whyNot(index, give, take) {
  if (!index.materials.has(give) || !index.materials.has(take)) return 'not_tradeable';
  if (give === take) return 'same_material';
  return 'different_trader';
}

/**
 * Exact quote for one exchange. `owned` null means stock unknown: the arithmetic is
 * shown but nothing is called affordable. `protected` is stock reserved for builds.
 */
export function quote(index, give, take, { receive = null, spend = null, owned, protected: reserved = {} }) {
  const pair = lot(index, give, take);
  if (!pair) return { possible: false, reason: whyNot(index, give, take) };
  const [pay, get] = pair;
  const source = index.materials.get(give);
  const target = index.materials.get(take);
  const lots = receive !== null ? Math.ceil(Math.max(receive, 0) / get) : spend !== null ? Math.floor(Math.max(spend, 0) / pay) : 1;
  const result = { give, take, pay, receive: get, rate: `${pay}:${get}`, lots, payTotal: lots * pay, receiveTotal: lots * get };
  const reasons = [];
  if (pay > source.cap) reasons.push('lot_exceeds_source_storage');
  if (lots < 1) reasons.push('below_one_lot');
  if (owned === null || owned === undefined) {
    return { ...result, possible: null, reason: 'inventory_unknown', reasons: reasons.length ? reasons : ['inventory_unknown'], maxLots: null };
  }
  const haveSource = owned[give] || 0;
  const haveTarget = owned[take] || 0;
  const spendable = Math.max(haveSource - (reserved[give] || 0), 0);
  const room = Math.max(target.cap - haveTarget, 0);
  const maxLots = Math.min(Math.floor(spendable / pay), Math.floor(room / get));
  if (lots * pay > spendable) reasons.push(lots * pay <= haveSource ? 'reserved_for_builds' : 'insufficient_stock');
  if (lots * get > room) reasons.push('destination_full');
  return {
    ...result,
    possible: reasons.length === 0,
    reason: reasons[0] || null,
    reasons,
    maxLots,
    spendable,
    sourceBefore: haveSource,
    sourceAfter: haveSource - lots * pay,
    targetBefore: haveTarget,
    targetAfter: haveTarget + lots * get,
    targetCap: target.cap,
  };
}

/** Apply basket trades in order; each step sees the state the previous one left. */
export function simulate(index, trades, owned, reserved = {}) {
  if (owned === null || owned === undefined) {
    return {
      known: false,
      valid: null,
      steps: trades.map((trade, i) => ({ index: i, ...quote(index, trade.give, trade.take, { spend: trade.lots * (lot(index, trade.give, trade.take)?.[0] || 0), owned: null }) })),
      after: null,
      changes: {},
    };
  }
  const state = { ...owned };
  const steps = [];
  let valid = true;
  for (let i = 0; i < trades.length; i += 1) {
    const trade = trades[i];
    const pair = lot(index, trade.give, trade.take);
    if (!pair) {
      steps.push({ index: i, possible: false, reason: whyNot(index, trade.give, trade.take), valid: false });
      valid = false;
      break;
    }
    const check = quote(index, trade.give, trade.take, { spend: trade.lots * pair[0], owned: state, protected: reserved });
    steps.push({ index: i, ...check, valid: Boolean(check.possible) });
    if (!check.possible) { valid = false; break; }
    state[trade.give] = check.sourceAfter;
    state[trade.take] = check.targetAfter;
  }
  const changes = {};
  new Set([...Object.keys(state), ...Object.keys(owned)]).forEach((key) => {
    const delta = (state[key] || 0) - (owned[key] || 0);
    if (delta) changes[key] = delta;
  });
  return { known: true, valid, steps, after: state, changes };
}

export const REASON_TEXT = {
  not_tradeable: 'Not a Material Trader material (Guardian, Thargoid and other special materials are not traded).',
  same_material: 'Choose a different material to give.',
  different_trader: 'Raw, manufactured and encoded materials are traded at different traders and cannot be exchanged for one another.',
  lot_exceeds_source_storage: 'One exchange needs more than this material can be stored. Trade through an intermediate grade.',
  below_one_lot: 'Less than one whole exchange.',
  insufficient_stock: 'Not enough held.',
  reserved_for_builds: 'Would spend stock reserved for your planned builds.',
  destination_full: 'Would exceed the storage limit for the material received.',
  inventory_unknown: 'Stock is unknown, so affordability is not checked.',
};
